use i2r_candidate::{map, List};
use std::cell::Cell;

fn collect_i32(xs: &List<i32>) -> Vec<i32> {
    match xs {
        List::Nil => Vec::new(),
        List::Cons(head, tail) => {
            let mut rest = collect_i32(tail.as_ref());
            let mut out = Vec::with_capacity(1 + rest.len());
            out.push(*head);
            out.append(&mut rest);
            out
        }
    }
}

struct NoCloneA { n: i32 }
struct NoCloneB { n: i32 }

#[test]
fn map_nil_returns_nil_without_calling_function() {
    let called = Cell::new(0usize);
    let out: List<i32> = map(
        |x: i32| {
            called.set(called.get() + 1);
            x
        },
        List::Nil,
    );
    assert_eq!(called.get(), 0);
    match out {
        List::Nil => {}
        List::Cons(_, _) => panic!(),
    }
}

#[test]
fn map_singleton_applies_function_once() {
    let called = Cell::new(0usize);
    let input = List::Cons(41i32, Box::new(List::Nil));
    let out = map(
        |x: i32| {
            called.set(called.get() + 1);
            x + 1
        },
        input,
    );
    assert_eq!(called.get(), 1);
    match out {
        List::Cons(42, tail) => match *tail {
            List::Nil => {}
            List::Cons(_, _) => panic!(),
        },
        List::Nil => panic!(),
    }
}

#[test]
fn map_preserves_order_and_multiplicity() {
    let called = Cell::new(0usize);
    let input = List::Cons(
        1i32,
        Box::new(List::Cons(
            2i32,
            Box::new(List::Cons(
                2i32,
                Box::new(List::Cons(3i32, Box::new(List::Nil))),
            )),
        )),
    );
    let out = map(
        |x: i32| {
            called.set(called.get() + 1);
            x * 10
        },
        input,
    );
    assert_eq!(called.get(), 4);
    assert_eq!(collect_i32(&out), vec![10, 20, 20, 30]);
}

#[test]
fn map_does_not_require_clone_or_ord() {
    let input = List::Cons(
        NoCloneA { n: 5 },
        Box::new(List::Cons(
            NoCloneA { n: -1 },
            Box::new(List::Nil),
        )),
    );
    let out: List<NoCloneB> = map(|a: NoCloneA| NoCloneB { n: a.n * 2 }, input);
    match out {
        List::Cons(NoCloneB { n: 10 }, tail) => match *tail {
            List::Cons(NoCloneB { n: -2 }, tail2) => match *tail2 {
                List::Nil => {}
                List::Cons(_, _) => panic!(),
            },
            List::Nil => panic!(),
            List::Cons(_, _) => panic!(),
        },
        List::Nil => panic!(),
        List::Cons(_, _) => panic!(),
    }
}

#[test]
fn list_nil_and_cons_expose_source_structure() {
    let nil_i32: List<i32> = List::Nil;
    let nil_string: List<String> = List::Nil;
    match nil_i32 {
        List::Nil => {}
        List::Cons(_, _) => panic!(),
    }
    match nil_string {
        List::Nil => {}
        List::Cons(_, _) => panic!(),
    }

    let singleton = List::Cons(9u8, Box::new(List::Nil));
    match singleton {
        List::Cons(head, tail) => {
            assert_eq!(head, 9u8);
            match *tail {
                List::Nil => {}
                List::Cons(_, _) => panic!(),
            }
        }
        List::Nil => panic!(),
    }

    let repeated = List::Cons(
        1i32,
        Box::new(List::Cons(1i32, Box::new(List::Nil))),
    );
    match repeated {
        List::Cons(1, tail) => match *tail {
            List::Cons(1, tail2) => match *tail2 {
                List::Nil => {}
                List::Cons(_, _) => panic!(),
            },
            _ => panic!(),
        },
        _ => panic!(),
    }
}

