/// Generic algebraic list with exactly the source constructors Nil and Cons.
pub enum List<T> {
    Nil,
    Cons(T, Box<List<T>>),
}

/// Source equations:
///   map f [] = []
///   map f (x # xs) = f x # map f xs
pub fn map<A, B, F>(f: F, xs: List<A>) -> List<B>
where
    F: Fn(A) -> B,
{
    match xs {
        List::Nil => List::Nil,
        List::Cons(x, xs) => {
            let y = f(x);
            let ys = map(f, *xs);
            List::Cons(y, Box::new(ys))
        }
    }
}

